#include <algorithm>
#include <cstdio>

const int INF = 1 << 29;

int n, m;
int d[3000][3000][2]; // Combine the two 2D arrays into one 3D array

void floydWarshall() {
    for (int k = 0; k != n; ++k) {
        for (int i = 0; i != n; ++i) {
            for (int j = 0; j != n; ++j) {
                // We can directly update the 3D array
                d[i][j][0] = std::min(d[i][j][0], d[i][k][0] + d[k][j][0]);
                d[i][j][1] = std::min(d[i][j][1], d[i][k][1] + d[k][j][1]);
            }
        }
    }
}

int main() {
    while (scanf("%d %d", &n, &m), n | m) {
        for (int i = 0; i != n; ++i)
            for (int j = 0; j != n; ++j)
                for (int k = 0; k != 2; ++k)
                    d[i][j][k] = i == j ? 0 : INF; // Initialize the combined array

        for (int i = 0; i != n; ++i) {
            int a, b, c, t;
            scanf("%d %d %d %d", &a, &b, &c, &t);
            d[a - 1][b - 1][0] = d[b - 1][a - 1][0] = c;
            d[a - 1][b - 1][1] = d[b - 1][a - 1][1] = t;
        }

        floydWarshall();

        int k;
        scanf("%d", &k);
        while (k--) {
            int p, q, r;
            scanf("%d %d %d", &p, &q, &r);
            printf("%d\n", d[p - 1][q - 1][r]); // Access the combined array directly
        }
    }
    return 0;
}

